      {
        "name": "scoreboard.py",
        "content": "import turtle as t\n\nALIGNMENT = \"center\"\nFONT = (\"Courier\", 40, \"bold\")\n\n\nclass Scoreboard(t.Turtle):\n    \"\"\"Manages player scores, net rendering, and score HUD for Pong Arcade.\"\"\"\n\n    def __init__(self):\n        super().__init__()\n        self.color(\"#cdd6f4\")\n        self.penup()\n        self.hideturtle()\n        self.l_score = 0\n        self.r_score = 0\n        self.draw_net()\n        self.update_scoreboard()\n\n    def draw_net(self) -> None:\n        \"\"\"Draws a dashed vertical center net line.\"\"\"\n        net = t.Turtle()\n        net.hideturtle()\n        net.color(\"#45475a\")\n        net.pensize(4)\n        net.penup()\n        net.goto(0, -290)\n        net.setheading(90)\n        while net.ycor() < 290:\n            net.pendown()\n            net.forward(15)\n            net.penup()\n            net.forward(15)\n\n    def update_scoreboard(self) -> None:\n        \"\"\"Renders current left and right player scores.\"\"\"\n        self.clear()\n        self.goto(-100, 220)\n        self.write(self.l_score, align=ALIGNMENT, font=FONT)\n        self.goto(100, 220)\n        self.write(self.r_score, align=ALIGNMENT, font=FONT)\n\n    def l_point(self) -> None:\n        \"\"\"Increments Left Player score by 1 point.\"\"\"\n        self.l_score += 1\n        self.update_scoreboard()\n\n    def r_point(self) -> None:\n        \"\"\"Increments Right Player score by 1 point.\"\"\"\n        self.r_score += 1\n        self.update_scoreboard()\n"
      }
