      {
        "name": "models.py",
        "content": "\"\"\"\nDay 68: User Authentication Model Definitions\nIntegrates Flask-Login UserMixin with modern SQLAlchemy 2.0 ORM.\n\"\"\"\n\nfrom flask_sqlalchemy import SQLAlchemy\nfrom flask_login import UserMixin\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column\nfrom sqlalchemy import Integer, String\n\n\nclass Base(DeclarativeBase):\n    pass\n\n\ndb = SQLAlchemy(model_class=Base)\n\n\nclass User(UserMixin, db.Model):\n    __tablename__ = \"users\"\n\n    id: Mapped[int] = mapped_column(Integer, primary_key=True)\n    email: Mapped[str] = mapped_column(String(100), unique=True, nullable=False)\n    password: Mapped[str] = mapped_column(String(250), nullable=False)\n    name: Mapped[str] = mapped_column(String(1000), nullable=False)\n\n    def __repr__(self) -> str:\n        return f\"<User #{self.id}: {self.email} ({self.name})>\"\n"
      },
      {
        "name": "server.py",
        "content": "\"\"\"\nDay 68: User Authentication with Flask-Login & Werkzeug Server\nImplements PBKDF2:SHA256 password hashing, user session lifecycle,\nflash messaging, and authenticated file downloads.\n\"\"\"\n\nimport os\nfrom flask import (\n    Flask,\n    render_template,\n    request,\n    url_for,\n    redirect,\n    flash,\n    send_from_directory,\n)\nfrom werkzeug.security import generate_password_hash, check_password_hash\nfrom flask_login import (\n    LoginManager,\n    login_user,\n    login_required,\n    current_user,\n    logout_user,\n)\nfrom models import db, User\n\napp = Flask(__name__)\napp.config[\"SECRET_KEY\"] = os.environ.get(\"FLASK_SECRET_KEY\", \"flask_login_auth_secret_key_demo\")\napp.config[\"SQLALCHEMY_DATABASE_URI\"] = \"sqlite:///users.db\"\napp.config[\"SQLALCHEMY_TRACK_MODIFICATIONS\"] = False\n\ndb.init_app(app)\n\n# Initialize Flask-Login\nlogin_manager = LoginManager()\nlogin_manager.login_view = \"login\"\nlogin_manager.init_app(app)\n\n\n@login_manager.user_loader\ndef load_user(user_id):\n    return db.session.get(User, int(user_id))\n\n\nwith app.app_context():\n    db.create_all()\n\n\n@app.route(\"/\")\ndef home():\n    return render_template(\"index.html\")\n\n\n@app.route(\"/register\", methods=[\"GET\", \"POST\"])\ndef register():\n    if request.method == \"POST\":\n        email = request.form.get(\"email\", \"\").strip().lower()\n        name = request.form.get(\"name\", \"\").strip()\n        raw_password = request.form.get(\"password\", \"\")\n\n        # Check if user already registered\n        existing_user = db.session.execute(db.select(User).where(User.email == email)).scalar()\n        if existing_user:\n            flash(\"You've already signed up with that email, log in instead!\")\n            return redirect(url_for(\"login\"))\n\n        # Hash and salt password with PBKDF2:SHA256\n        hashed_password = generate_password_hash(\n            raw_password,\n            method=\"pbkdf2:sha256\",\n            salt_length=8\n        )\n\n        new_user = User(\n            email=email,\n            name=name,\n            password=hashed_password\n        )\n        db.session.add(new_user)\n        db.session.commit()\n\n        # Log in newly registered user\n        login_user(new_user)\n        return redirect(url_for(\"secrets\"))\n\n    return render_template(\"register.html\")\n\n\n@app.route(\"/login\", methods=[\"GET\", \"POST\"])\ndef login():\n    if request.method == \"POST\":\n        email = request.form.get(\"email\", \"\").strip().lower()\n        password = request.form.get(\"password\", \"\")\n\n        user = db.session.execute(db.select(User).where(User.email == email)).scalar()\n\n        if not user:\n            flash(\"That email does not exist. Please check or register a new account.\")\n            return redirect(url_for(\"login\"))\n        elif not check_password_hash(user.password, password):\n            flash(\"Password incorrect, please try again.\")\n            return redirect(url_for(\"login\"))\n        else:\n            login_user(user)\n            return redirect(url_for(\"secrets\"))\n\n    return render_template(\"login.html\")\n\n\n@app.route(\"/secrets\")\n@login_required\ndef secrets():\n    return render_template(\"secrets.html\", name=current_user.name)\n\n\n@app.route(\"/download\")\n@login_required\ndef download():\n    file_dir = os.path.join(app.root_path, \"static\", \"files\")\n    return send_from_directory(\n        directory=file_dir,\n        path=\"cheat_sheet.pdf\",\n        as_attachment=True\n    )\n\n\n@app.route(\"/logout\")\n@login_required\ndef logout():\n    logout_user()\n    return redirect(url_for(\"home\"))\n\n\nif __name__ == \"__main__\":\n    print(\"\ud83c\udf10 Starting Day 68 Flask-Login Auth Server on http://127.0.0.1:5000 ...\")\n    app.run(debug=True, port=5000)\n"
      }
